+    }
+    let (st, turn) = first;
+    for b in steel.stack.iter().filter(|b| b.hi - b.lo > 0.0) {
+        let mid = 0.5 * (b.lo + b.hi);
+        let probe = add(lerp(st.p0, st.p1, 0.5), st.axis, mid);
+        let probe = turn.map_or(probe, |t| turn_about(&t.ax, probe, t.th));
