+        let mut owners = steel.fixtures.iter().filter(|f| f.aabb == b);
+        match (twins, owners.next(), owners.next()) {
+            (1, Some(f), None) => meshed.push((fixed, b, f)),
+            _ if fixed => plain_f.push(b),
+            _ => plain_t.push(b),
